create extension if not exists pgcrypto;
create table if not exists organizations (id uuid primary key default gen_random_uuid(), name text not null unique, variance_threshold_pct numeric not null default 5, variance_threshold_units integer not null default 10, created_at timestamptz not null default now());
create table if not exists users (id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations(id) on delete cascade, role text not null check (role in ('admin','counter','auditor')), full_name text not null, email text not null unique, phone text, password_hash text, is_active boolean not null default true, setup_status text not null default 'invited', email_verified boolean not null default false, email_confirmation_token text, invite_code text, created_at timestamptz not null default now());
create table if not exists locations (id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations(id) on delete cascade, name text not null, type text not null check (type in ('warehouse','store','site')), address text, created_at timestamptz not null default now());
create table if not exists zones (id uuid primary key default gen_random_uuid(), location_id uuid not null references locations(id) on delete cascade, name text not null, code text, created_at timestamptz not null default now());
create table if not exists items (id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations(id) on delete cascade, zone_id uuid not null references zones(id), name text not null, barcode text, sku text not null, unit text not null default 'unit', category text, system_qty numeric not null default 0, image_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(org_id, sku));
create table if not exists count_sessions (id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations(id) on delete cascade, location_id uuid references locations(id), zone_id uuid references zones(id), name text not null, status text not null default 'draft', mode text not null check (mode in ('blind','visible','double')), item_ids uuid[] not null default '{}', assigned_counter_id uuid references users(id) on delete set null, assigned_counter_2_id uuid references users(id) on delete set null, auditor_id uuid references users(id) on delete set null, submitted_at timestamptz, approved_at timestamptz, rejected_at timestamptz, reject_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists count_entries (id uuid primary key default gen_random_uuid(), session_id uuid not null references count_sessions(id) on delete cascade, item_id uuid not null references items(id), counted_qty numeric not null, system_qty numeric not null, variance numeric not null, counted_by uuid references users(id) on delete set null, counted_at timestamptz not null default now(), is_flagged boolean not null default false, notes text, count_round integer not null default 1, witnessed boolean not null default false, witness_name text);
create table if not exists audit_logs (id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations(id) on delete cascade, entity_type text not null, entity_id uuid not null, action text not null, actor_id uuid references users(id) on delete set null, payload jsonb not null default '{}'::jsonb, reason text, created_at timestamptz not null default now());
create table if not exists excel_uploads (id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations(id) on delete cascade, file_name text not null, raw_data jsonb not null default '[]'::jsonb, columns jsonb not null default '[]'::jsonb, rows_preview jsonb not null default '[]'::jsonb, imported_count integer not null default 0, zone_id uuid references zones(id), uploaded_by uuid references users(id) on delete set null, created_at timestamptz not null default now());
create table if not exists count_reports (id uuid primary key default gen_random_uuid(), org_id uuid not null references organizations(id) on delete cascade, session_id uuid not null references count_sessions(id) on delete cascade, submitted_by uuid references users(id) on delete set null, report_type text not null check (report_type in ('auditor','admin')), summary text, items_summary jsonb not null default '[]'::jsonb, total_items int not null default 0, matched_items int not null default 0, variance_items int not null default 0, status text not null default 'draft', created_at timestamptz not null default now(), unique(session_id));
create index if not exists users_org_idx on users(org_id); create index if not exists items_org_idx on items(org_id); create index if not exists sessions_org_idx on count_sessions(org_id); create index if not exists entries_session_idx on count_entries(session_id); create index if not exists excel_uploads_org_idx on excel_uploads(org_id); create index if not exists locations_org_idx on locations(org_id); create index if not exists zones_location_idx on zones(location_id); create index if not exists audit_logs_org_idx on audit_logs(org_id); create index if not exists reports_org_idx on count_reports(org_id);
